mkdir -p /app/submission && cat > /app/submission/main.py <<'PYEOF'
#!/usr/bin/env python3
"""Offline SIP identity boundary auditor (Boundary Profile 1)."""
import sys
import json
import re
import hashlib

ANON = 'sip:anonymous@anonymous.invalid'

class Invalid(Exception):
    pass

class UErr(Exception):
    pass

class Reject(Exception):
    def __init__(self, reason):
        self.reason = reason

ID_RE = re.compile(r'^[A-Za-z][A-Za-z0-9_-]{0,31}$')
TOKEN_PAT = r"[A-Za-z0-9.!%*_+`'~\-]+"
TOKEN_RE = re.compile(TOKEN_PAT)
CALLID_RE = re.compile(r'^[A-Za-z0-9_.@-]{1,64}$')
HEXCHARS = set('0123456789abcdefABCDEF')
USER_SET = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.!~*'()")
COMPACT = {'f': 'from', 't': 'to', 'i': 'call-id', 'l': 'content-length'}


def is_int(x):
    return type(x) is int


# ---------------------------------------------------------------------------
# URI parsing
# ---------------------------------------------------------------------------

def parse_uri(s):
    low = s.lower()
    if low.startswith('tel:'):
        return parse_tel(s)
    if low.startswith('sips:'):
        return parse_sip(s, 'sips', 5)
    if low.startswith('sip:'):
        return parse_sip(s, 'sip', 4)
    raise UErr()


def parse_tel(s):
    body = s[4:]
    if not body or body[0] != '+':
        raise UErr()
    rest = body[1:]
    if not rest:
        raise UErr()
    digits = []
    for ch in rest:
        if '0' <= ch <= '9':
            digits.append(ch)
        elif ch in '-.()':
            pass
        else:
            raise UErr()
    d = ''.join(digits)
    if not (3 <= len(d) <= 15):
        raise UErr()
    if not ('1' <= d[0] <= '9'):
        raise UErr()
    return ('tel:+' + d, 'tel')


def decode_user(u):
    out = []
    i = 0
    n = len(u)
    while i < n:
        c = u[i]
        if c == '%':
            if i + 2 >= n:
                raise UErr()
            hh = u[i + 1:i + 3]
            if len(hh) != 2 or hh[0] not in HEXCHARS or hh[1] not in HEXCHARS:
                raise UErr()
            b = int(hh, 16)
            ch = chr(b)
            if ch not in USER_SET:
                raise UErr()
            out.append(ch)
            i += 3
        else:
            if c not in USER_SET:
                raise UErr()
            out.append(c)
            i += 1
    res = ''.join(out)
    if not (1 <= len(res) <= 64):
        raise UErr()
    return res


def validate_host(host):
    if len(host) < 1 or len(host) > 253:
        raise UErr()
    labels = host.split('.')
    if len(labels) < 2:
        raise UErr()
    for lab in labels:
        if len(lab) < 1 or len(lab) > 63:
            raise UErr()
        if not re.fullmatch(r'[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?', lab):
            raise UErr()
    if not ('a' <= labels[-1][0].lower() <= 'z'):
        raise UErr()


def parse_sip(s, scheme, plen):
    rest = s[plen:]
    if rest.count('@') != 1:
        raise UErr()
    user_raw, hostport = rest.split('@')
    user = decode_user(user_raw)
    if hostport == '':
        raise UErr()
    if ':' in hostport:
        parts = hostport.split(':')
        if len(parts) != 2:
            raise UErr()
        host = parts[0]
        portstr = parts[1]
        if portstr == '' or len(portstr) > 5:
            raise UErr()
        if not all('0' <= c <= '9' for c in portstr):
            raise UErr()
        pv = int(portstr)
        if not (1 <= pv <= 65535):
            raise UErr()
        port = pv
    else:
        host = hostport
        port = None
    validate_host(host)
    canon = scheme + ':' + user + '@' + host.lower()
    if port is not None:
        canon += ':' + str(port)
    return (canon, scheme)


# ---------------------------------------------------------------------------
# Address parsing
# ---------------------------------------------------------------------------

def validate_display_name(np):
    if np == '':
        return
    if np[0] == '"':
        i = 1
        n = len(np)
        closed = -1
        while i < n:
            c = np[i]
            if c == '\\':
                if i + 1 >= n:
                    raise UErr()
                nx = np[i + 1]
                if not (nx == '\t' or (0x20 <= ord(nx) <= 0x7e)):
                    raise UErr()
                i += 2
                continue
            if c == '"':
                closed = i
                break
            else:
                if not (c == '\t' or c == ' ' or (0x21 <= ord(c) <= 0x7e)):
                    raise UErr()
                i += 1
        if closed < 0:
            raise UErr()
        rest = np[closed + 1:]
        if rest.strip(' \t') != '':
            raise UErr()
    else:
        core = np.strip(' \t')
        if core == '':
            return
        parts = re.split(r'[ \t]+', core)
        for p in parts:
            if not TOKEN_RE.fullmatch(p):
                raise UErr()


def parse_address(s):
    if s == '':
        raise UErr()
    if '<' in s or '>' in s:
        if s.count('<') != 1 or s.count('>') != 1:
            raise UErr()
        lt = s.find('<')
        gt = s.find('>')
        if gt < lt:
            raise UErr()
        if gt != len(s) - 1:
            raise UErr()
        inside = s[lt + 1:gt]
        if inside == '':
            raise UErr()
        if any(c in ' \t\r\n' for c in inside):
            raise UErr()
        validate_display_name(s[:lt])
        return parse_uri(inside)
    else:
        if any(c in ' \t' for c in s):
            raise UErr()
        return parse_uri(s)


def split_addr_params(s):
    depth = 0
    inq = False
    esc = False
    for i, ch in enumerate(s):
        if inq:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                inq = False
        else:
            if ch == '"':
                inq = True
            elif ch == '<':
                depth += 1
            elif ch == '>':
                if depth > 0:
                    depth -= 1
            elif ch == ';' and depth == 0:
                return s[:i], s[i:]
    return s, ''


def split_commas(s):
    parts = []
    depth = 0
    inq = False
    esc = False
    start = 0
    for i, ch in enumerate(s):
        if inq:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                inq = False
        else:
            if ch == '"':
                inq = True
            elif ch == '<':
                depth += 1
            elif ch == '>':
                if depth > 0:
                    depth -= 1
            elif ch == ',' and depth == 0:
                parts.append(s[start:i])
                start = i + 1
    parts.append(s[start:])
    return parts


# ---------------------------------------------------------------------------
# Request syntax parsing
# ---------------------------------------------------------------------------

def validate_header_bytes(hb):
    n = len(hb)
    for i in range(n):
        b = hb[i]
        if b == 13:
            if i + 1 >= n or hb[i + 1] != 10:
                raise Reject('syntax')
        elif b == 10:
            if i == 0 or hb[i - 1] != 13:
                raise Reject('syntax')
        else:
            if not (b == 9 or (0x20 <= b <= 0x7e)):
                raise Reject('syntax')


def parse_start_line(s):
    parts = s.split(' ')
    if len(parts) != 3:
        raise Reject('syntax')
    method, uri, ver = parts
    if method not in ('INVITE', 'MESSAGE'):
        raise Reject('syntax')
    if ver != 'SIP/2.0':
        raise Reject('syntax')
    try:
        canon, cat = parse_uri(uri)
    except UErr:
        raise Reject('syntax')
    if cat not in ('sip', 'sips'):
        raise Reject('syntax')
    return method, canon


def parse_headers(lines):
    result = []
    cur = None
    for raw in lines:
        if raw and raw[0] in (0x20, 0x09):
            if cur is None:
                raise Reject('syntax')
            cont = raw.lstrip(b' \t').decode('latin-1')
            prev = cur[1].rstrip(' \t')
            cur[1] = prev + ' ' + cont
        else:
            if cur is not None:
                result.append((cur[0], cur[1].strip(' \t')))
                cur = None
            line = raw.decode('latin-1')
            ci = line.find(':')
            if ci < 0:
                raise Reject('syntax')
            namepart = line[:ci]
            value = line[ci + 1:]
            name = namepart.rstrip(' \t')
            if name == '' or any(ch in ' \t' for ch in name):
                raise Reject('syntax')
            if not TOKEN_RE.fullmatch(name):
                raise Reject('syntax')
            lower = name.lower()
            norm = COMPACT.get(lower, lower)
            cur = [norm, value]
    if cur is not None:
        result.append((cur[0], cur[1].strip(' \t')))
    return result


def parse_request(wire_hex):
    if len(wire_hex) % 2 != 0:
        raise Reject('hex')
    for c in wire_hex:
        if c not in HEXCHARS:
            raise Reject('hex')
    data = bytes.fromhex(wire_hex)

    if len(data) > 65536:
        raise Reject('syntax')
    idx = data.find(b'\r\n\r\n')
    if idx < 0:
        raise Reject('syntax')
    header_block = data[:idx]
    body = data[idx + 4:]
    if len(header_block) > 32768:
        raise Reject('syntax')
    validate_header_bytes(header_block)
    lines = header_block.split(b'\r\n')
    if len(lines) - 1 > 256:
        raise Reject('syntax')
    for ln in lines:
        if len(ln) > 8192:
            raise Reject('syntax')
    start = lines[0].decode('latin-1')
    method, target = parse_start_line(start)
    headers = parse_headers(lines[1:])
    return {'method': method, 'target': target, 'body': body, 'headers': headers}


def check_singletons(headers):
    cnt = {}
    for norm, val in headers:
        cnt[norm] = cnt.get(norm, 0) + 1
    for req in ('from', 'to', 'call-id', 'content-length', 'cseq'):
        if cnt.get(req, 0) != 1:
            raise Reject('headers')


def getfield(headers, name):
    for norm, val in headers:
        if norm == name:
            return val
    return None


def check_length(headers, body):
    cl = None
    for norm, val in headers:
        if norm == 'content-length':
            cl = val
    if cl is None or not re.fullmatch(r'[0-9]{1,10}', cl):
        raise Reject('length')
    if int(cl) != len(body):
        raise Reject('length')


def parse_from(value):
    addr, params = split_addr_params(value)
    addr = addr.strip(' \t')
    canon, cat = parse_address(addr)
    m = re.fullmatch(r'[ \t]*;[ \t]*tag[ \t]*=[ \t]*(' + TOKEN_PAT + r')', params, re.IGNORECASE)
    if not m:
        raise UErr()
    tag = m.group(1)
    if not (1 <= len(tag) <= 32):
        raise UErr()
    return canon, cat, tag


def parse_to(value, target):
    addr, params = split_addr_params(value)
    if params != '':
        raise UErr()
    addr = addr.strip(' \t')
    canon, cat = parse_address(addr)
    if cat not in ('sip', 'sips'):
        raise UErr()
    if canon != target:
        raise UErr()
    return canon


def parse_id_header(rows):
    items = []
    for row in rows:
        for piece in split_commas(row):
            p = piece.strip(' \t')
            if p == '':
                raise UErr()
            addr, params = split_addr_params(p)
            if params != '':
                raise UErr()
            canon, cat = parse_address(addr.strip(' \t'))
            items.append((canon, cat))
    if len(items) == 0:
        raise UErr()
    if len(items) > 2:
        raise UErr()
    if len(items) == 2:
        cats = [c for u, c in items]
        sipc = sum(1 for c in cats if c in ('sip', 'sips'))
        telc = sum(1 for c in cats if c == 'tel')
        if not (sipc == 1 and telc == 1):
            raise UErr()
        if items[0][0] == items[1][0]:
            raise UErr()
        if cats[0] in ('sip', 'sips'):
            ordered = items
        else:
            ordered = [items[1], items[0]]
    else:
        ordered = items
    return [u for u, c in ordered]


def parse_privacy(rows):
    if not rows:
        return 'absent'
    toks = []
    for row in rows:
        for item in row.split(';'):
            t = item.strip(' \t').lower()
            if t not in ('id', 'none'):
                raise UErr()
            toks.append(t)
    hasid = 'id' in toks
    hasnone = 'none' in toks
    if hasid and hasnone:
        raise UErr()
    if hasid:
        return 'id'
    if hasnone:
        return 'none'
    return 'absent'


def parse_fields(headers, target, method):
    fromv = getfield(headers, 'from')
    tov = getfield(headers, 'to')
    callid = getfield(headers, 'call-id')
    cseqv = getfield(headers, 'cseq')

    from_canon, from_cat, tag = parse_from(fromv)
    parse_to(tov, target)
    if not CALLID_RE.fullmatch(callid):
        raise UErr()
    m = re.fullmatch(r'([0-9]{1,10})[ \t]+([^ \t]+)', cseqv)
    if not m:
        raise UErr()
    num = int(m.group(1))
    meth = m.group(2)
    if not (1 <= num <= 2147483647):
        raise UErr()
    if meth != method:
        raise UErr()

    pai_rows = [v for n, v in headers if n == 'p-asserted-identity']
    ppi_rows = [v for n, v in headers if n == 'p-preferred-identity']
    pai = parse_id_header(pai_rows) if pai_rows else None
    ppi = parse_id_header(ppi_rows) if ppi_rows else None
    priv_rows = [v for n, v in headers if n == 'privacy']
    privacy = parse_privacy(priv_rows)
    return {
        'from_uri': from_canon,
        'from_cat': from_cat,
        'tag': tag,
        'call_id': callid,
        'cseq': num,
        'pai': pai,
        'ppi': ppi,
        'privacy': privacy,
    }


# ---------------------------------------------------------------------------
# Envelope loading / validation
# ---------------------------------------------------------------------------

def no_dup(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise ValueError('duplicate key')
        d[k] = v
    return d


def bad_const(x):
    raise ValueError('bad constant')


def load_envelope(raw):
    if len(raw) > 33554432:
        raise Invalid()
    if raw[:3] == b'\xef\xbb\xbf':
        raise Invalid()
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise Invalid()
    try:
        doc = json.loads(text, object_pairs_hook=no_dup, parse_constant=bad_const)
    except Exception:
        raise Invalid()

    if type(doc) is not dict:
        raise Invalid()
    if set(doc.keys()) != {'version', 'config', 'events'}:
        raise Invalid()
    if not (is_int(doc['version']) and doc['version'] == 1):
        raise Invalid()

    cfg = doc['config']
    if type(cfg) is not dict or set(cfg.keys()) != {'accounts', 'peers', 'ttl_ms', 'capacity'}:
        raise Invalid()
    accounts = cfg['accounts']
    peers = cfg['peers']
    ttl = cfg['ttl_ms']
    cap = cfg['capacity']
    if type(accounts) is not list or len(accounts) > 256:
        raise Invalid()
    if not (is_int(ttl) and 1 <= ttl <= 1000000):
        raise Invalid()
    if not (is_int(cap) and 1 <= cap <= 10000):
        raise Invalid()
    if type(peers) is not list or not (1 <= len(peers) <= 256):
        raise Invalid()

    acct_ids = set()
    alias_to_account = {}
    account_info = {}
    for a in accounts:
        if type(a) is not dict or set(a.keys()) != {'id', 'default', 'aliases'}:
            raise Invalid()
        aid = a['id']
        if not (isinstance(aid, str) and ID_RE.fullmatch(aid)):
            raise Invalid()
        if aid in acct_ids:
            raise Invalid()
        acct_ids.add(aid)
        aliases = a['aliases']
        if type(aliases) is not list or not (1 <= len(aliases) <= 8):
            raise Invalid()
        seen = set()
        for al in aliases:
            if not isinstance(al, str):
                raise Invalid()
            try:
                canon, cat = parse_uri(al)
            except UErr:
                raise Invalid()
            if canon != al:
                raise Invalid()
            if al == ANON:
                raise Invalid()
            if al in seen:
                raise Invalid()
            seen.add(al)
            if al in alias_to_account:
                raise Invalid()
            alias_to_account[al] = aid
        dflt = a['default']
        if not isinstance(dflt, str) or dflt not in seen:
            raise Invalid()
        account_info[aid] = {'default': dflt, 'aliases': seen}

    peer_info = {}
    peer_ids = set()
    for p in peers:
        if type(p) is not dict or set(p.keys()) != {'id', 'mode', 'accounts'}:
            raise Invalid()
        pid = p['id']
        if not (isinstance(pid, str) and ID_RE.fullmatch(pid)):
            raise Invalid()
        if pid in peer_ids:
            raise Invalid()
        peer_ids.add(pid)
        mode = p['mode']
        if mode not in ('access', 'relay'):
            raise Invalid()
        pacc = p['accounts']
        if type(pacc) is not list:
            raise Invalid()
        allowed = set()
        if mode == 'access':
            if len(pacc) != 0:
                raise Invalid()
        else:
            for x in pacc:
                if not isinstance(x, str):
                    raise Invalid()
                if x not in acct_ids:
                    raise Invalid()
                if x in allowed:
                    raise Invalid()
                allowed.add(x)
        peer_info[pid] = {'mode': mode, 'allowed': allowed}

    evs = doc['events']
    if type(evs) is not list or len(evs) > 10000:
        raise Invalid()
    evlist = []
    prev_t = -1
    total = 0
    for e in evs:
        if type(e) is not dict or set(e.keys()) != {'t', 'peer', 'auth', 'egress', 'wire_hex'}:
            raise Invalid()
        t = e['t']
        if not (is_int(t) and 0 <= t <= 9007199254740991):
            raise Invalid()
        if t < prev_t:
            raise Invalid()
        prev_t = t
        peer = e['peer']
        if not isinstance(peer, str) or peer not in peer_ids:
            raise Invalid()
        auth = e['auth']
        if auth is not None:
            if not isinstance(auth, str) or auth not in acct_ids:
                raise Invalid()
        egress = e['egress']
        if egress not in ('internal', 'external'):
            raise Invalid()
        wh = e['wire_hex']
        if not isinstance(wh, str):
            raise Invalid()
        if len(wh) > 131072:
            raise Invalid()
        total += len(wh) // 2
        if total > 8388608:
            raise Invalid()
        if peer_info[peer]['mode'] == 'relay' and auth is not None:
            raise Invalid()
        evlist.append((t, peer, auth, egress, wh))

    return {
        'account_info': account_info,
        'alias_to_account': alias_to_account,
        'peer_info': peer_info,
        'ttl': ttl,
        'cap': cap,
        'events': evlist,
    }


# ---------------------------------------------------------------------------
# Processing
# ---------------------------------------------------------------------------

def process(cfg):
    account_info = cfg['account_info']
    alias_to_account = cfg['alias_to_account']
    peer_info = cfg['peer_info']
    ttl = cfg['ttl']
    cap = cfg['cap']

    entries = {}  # key -> {'commit': tuple, 'first': int, 'time': int}
    results = []
    accepted = replayed = rejected = 0

    for i, (t, peer, auth, egress, wire_hex) in enumerate(cfg['events']):
        # expiration step before every event
        if entries:
            dead = [k for k, e in entries.items() if t >= e['time'] + ttl]
            for k in dead:
                del entries[k]

        try:
            req = parse_request(wire_hex)
        except Reject as r:
            results.append({'index': i, 'decision': 'reject', 'reason': r.reason})
            rejected += 1
            continue

        headers = req['headers']
        try:
            check_singletons(headers)
            check_length(headers, req['body'])
            fld = parse_fields(headers, req['target'], req['method'])
        except Reject as r:
            results.append({'index': i, 'decision': 'reject', 'reason': r.reason})
            rejected += 1
            continue
        except UErr:
            results.append({'index': i, 'decision': 'reject', 'reason': 'fields'})
            rejected += 1
            continue

        method = req['method']
        target = req['target']
        body = req['body']
        privacy = fld['privacy']
        from_canon = fld['from_uri']
        tag = fld['tag']
        call_id = fld['call_id']
        cseq = fld['cseq']
        pai = fld['pai']
        ppi = fld['ppi']
        pmode = peer_info[peer]['mode']

        # policy
        reason = None
        account_id = None
        selected = None
        asserted = None
        if pmode == 'access':
            if auth is None:
                reason = 'auth'
            else:
                account_id = auth
                aliases = account_info[account_id]['aliases']
                if ppi is not None:
                    ok = True
                    for u in ppi:
                        if u not in aliases:
                            ok = False
                            break
                    if not ok:
                        reason = 'identity'
                    else:
                        selected = ppi[0]
                        asserted = ppi[:]
                else:
                    selected = account_info[account_id]['default']
                    asserted = [selected]
                if reason is None:
                    if not (from_canon in aliases or (from_canon == ANON and privacy == 'id')):
                        reason = 'identity'
        else:  # relay
            if ppi is not None or pai is None:
                reason = 'identity'
            else:
                owners = set()
                ok = True
                for u in pai:
                    o = alias_to_account.get(u)
                    if o is None:
                        ok = False
                        break
                    owners.add(o)
                if not ok or len(owners) != 1:
                    reason = 'identity'
                else:
                    owner = next(iter(owners))
                    if owner not in peer_info[peer]['allowed']:
                        reason = 'identity'
                    else:
                        account_id = owner
                        selected = pai[0]
                        asserted = pai[:]
                        aliases = account_info[owner]['aliases']
                        if not (from_canon in aliases or (from_canon == ANON and privacy == 'id')):
                            reason = 'identity'

        if reason is not None:
            results.append({'index': i, 'decision': 'reject', 'reason': reason})
            rejected += 1
            continue

        # ledger
        key = (peer, call_id, cseq, method)
        commit = (account_id, selected, tuple(asserted), from_canon, tag, target, privacy, egress, body)

        if key in entries:
            ent = entries[key]
            if ent['commit'] == commit:
                first = ent['first']
                decision = 'replay'
                replayed += 1
            else:
                results.append({'index': i, 'decision': 'reject', 'reason': 'conflict'})
                rejected += 1
                continue
        else:
            if len(entries) >= cap:
                victim = min(entries, key=lambda k: entries[k]['first'])
                del entries[victim]
            entries[key] = {'commit': commit, 'first': i, 'time': t}
            first = i
            decision = 'accept'
            accepted += 1

        if egress == 'external' and privacy in ('id', 'absent'):
            pai_out = []
        else:
            pai_out = asserted[:]
        from_out = ANON if privacy == 'id' else selected

        results.append({
            'index': i,
            'decision': decision,
            'first': first,
            'account': account_id,
            'identity': selected,
            'from': from_out,
            'pai': pai_out,
            'method': method,
            'target': target,
            'call_id': call_id,
            'cseq': cseq,
            'tag': tag,
            'privacy': privacy,
            'body_sha256': hashlib.sha256(body).hexdigest(),
        })

    return {
        'results': results,
        'accepted': accepted,
        'replayed': replayed,
        'rejected': rejected,
        'live': len(entries),
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        cfg = load_envelope(raw)
    except Invalid:
        sys.stderr.write('invalid envelope\n')
        return 2
    out = process(cfg)
    sys.stdout.write(json.dumps(out))
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
