new='''def find_opening_angle(s):
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"':
            i += 1
            closed = False
            while i < n:
                c2 = s[i]
                if c2 == '\\\\':
                    i += 2
                    continue
                if c2 == '"':
                    closed = True
                    i += 1
                    break
                i += 1
            if not closed:
                raise UErr()
        elif c == '<':
            return i
        elif c == '>':
            raise UErr()
        else:
            i += 1
    return -1


def parse_address(s):
